package main

import (
	"fmt"
	"os"
	"strings"
)

// Block types
const (
	BlockAir = iota
	BlockGrass
	BlockDirt
	BlockStone
	BlockWood
	BlockLeaves
	BlockSand
	BlockWater
	BlockPlank
	BlockCobblestone
	BlockBedrock
	BlockSnow
	BlockGravel
	MAX_BLOCK_TYPES
)

var BlockChars = []string{
	" ",  // Air
	"▒",  // Grass
	"▒",  // Dirt
	"█",  // Stone
	"▓",  // Wood
	"░",  // Leaves
	"░",  // Sand
	"~",  // Water
	"▒",  // Plank
	"█",  // Cobblestone
	"#",  // Bedrock
	"░",  // Snow
	"░",  // Gravel
}

var BlockColors = []string{
	"",        // Air
	"\033[32m", // Grass - green
	"\033[33m", // Dirt - brown
	"\033[37m", // Stone - white/gray
	"\033[31m", // Wood - red/brown
	"\033[32m", // Leaves - green
	"\033[33m", // Sand - yellow
	"\033[34m", // Water - blue
	"\033[33m", // Plank - brown
	"\033[37m", // Cobblestone
	"\033[30m", // Bedrock - dark
	"\033[37m", // Snow - white
	"\033[37m", // Gravel
}

var BlockNames = []string{
	"Air",
	"Grass",
	"Dirt",
	"Stone",
	"Wood",
	"Leaves",
	"Sand",
	"Water",
	"Plank",
	"Cobblestone",
	"Bedrock",
	"Snow",
	"Gravel",
}

// Game holds all state
type Game struct {
	Width, Height int // screen dimensions
	RenderWidth   int // in characters (2 chars per block for aspect)

	World    [][][]uint8 // [y][z][x] - y=up, z=depth, x=right
	WX, WY, WZ int       // world dimensions

	PlayerX, PlayerY, PlayerZ float64
	PlayerVX, PlayerVY, PlayerVZ float64
	Yaw, Pitch float64
	OnGround   bool
	Flying     bool

	Hotbar     [9]uint8 // block types in hotbar slots
	HotbarSel  int      // selected hotbar slot (0-8)
	Inventory  map[uint8]int

	Breaking  bool
	BreakTime float64

	Seed       int64
	Running    bool
	Creative   bool
	DayTime    float64
	FrameCount int

	// chunks in view
	cx, cz int // player chunk coords
}

func NewGame(w, h int) *Game {
	return &Game{
		Width:      w,
		Height:     h,
		RenderWidth: w * 2,
		Running:    true,
		Seed:       42,
		Hotbar:     [9]uint8{BlockGrass, BlockDirt, BlockStone, BlockWood, BlockPlank, BlockCobblestone, BlockSand, BlockGravel, BlockSnow},
		HotbarSel:  0,
		Inventory:  make(map[uint8]int),
		DayTime:    0,
		Creative:   false,
	}
}

func (g *Game) Init() {
	// Generate world: 64 wide, 32 tall, 64 deep
	g.WX, g.WY, g.WZ = 64, 32, 64
	g.World = make([][][]uint8, g.WY)
	for y := 0; y < g.WY; y++ {
		g.World[y] = make([][]uint8, g.WZ)
		for z := 0; z < g.WZ; z++ {
			g.World[y][z] = make([]uint8, g.WX)
		}
	}

	g.GenerateTerrain()

	// Place player
	g.PlayerX = float64(g.WX / 2)
	g.PlayerY = 8.0
	g.PlayerZ = float64(g.WZ / 2)
	g.PlayerVX, g.PlayerVY, g.PlayerVZ = 0, 0, 0
	g.Yaw = 0
	g.Pitch = 0
	g.OnGround = false
}

// Simple noise function - use seed
func (g *Game) noise(x, z int) float64 {
	n := int64(x)*374761393 + int64(z)*668265263 + g.Seed*1274126177
	n = (n ^ (n >> 13)) * 1274126177
	return float64(n&0x7fffffff) / float64(0x7fffffff)
}

func (g *Game) GenerateTerrain() {
	// Heightmap using simple pseudo-noise
	heightmap := make([][]int, g.WZ)
	for z := 0; z < g.WZ; z++ {
		heightmap[z] = make([]int, g.WX)
		for x := 0; x < g.WX; x++ {
			h := int(g.noise(x, z)*6 + g.noise(x*3, z*3)*3 + g.noise(x*6, z*6)*1.5)
			heightmap[z][x] = 4 + h
			if heightmap[z][x] < 1 {
				heightmap[z][x] = 1
			}
			if heightmap[z][x] > g.WY-2 {
				heightmap[z][x] = g.WY - 2
			}
		}
	}

	// Fill blocks
	for z := 0; z < g.WZ; z++ {
		for x := 0; x < g.WX; x++ {
			h := heightmap[z][x]

			// Bedrock at bottom
			g.World[0][z][x] = BlockBedrock

			// Stone
			for y := 1; y < h-2; y++ {
				g.World[y][z][x] = BlockStone
			}

			// Dirt layer
			for y := h - 2; y < h; y++ {
				if y >= 1 {
					g.World[y][z][x] = BlockDirt
				}
			}

			// Grass on top
			if h < g.WY-1 {
				g.World[h][z][x] = BlockGrass
			}

			// Trees (simple placement)
			if g.noise(x*7+3, z*11+5) > 0.85 && h < g.WY-8 {
				treeHeight := 4 + int(g.noise(x*13, z*17)*3)
				// Trunk
				for y := h + 1; y <= h+treeHeight && y < g.WY-1; y++ {
					g.World[y][z][x] = BlockWood
				}
				// Leaves
				leafStart := h + treeHeight - 2
				for dy := 0; dy <= 2 && leafStart+dy < g.WY; dy++ {
					radius := 2
					if dy == 0 {
						radius = 1
					}
					for dz := -radius; dz <= radius; dz++ {
						for dx := -radius; dx <= radius; dx++ {
							nz, nx := z+dz, x+dx
							if nz >= 0 && nz < g.WZ && nx >= 0 && nx < g.WX {
								if g.World[leafStart+dy][nz][nx] == BlockAir {
									g.World[leafStart+dy][nz][nx] = BlockLeaves
								}
							}
						}
					}
				}
			}
		}
	}

	// Add some ores/caves randomly (simplified - just stone variation)
	for i := 0; i < 20; i++ {
		cx := int(g.noise(i*100, 0) * float64(g.WX))
		cz := int(g.noise(0, i*100) * float64(g.WZ))
		cy := 2 + int(g.noise(i*50, i*50)*7)
		if cy >= 1 && cy < g.WY-1 && cz >= 0 && cz < g.WZ && cx >= 0 && cx < g.WX {
			for dy := -1; dy <= 1; dy++ {
				for dz := -1; dz <= 1; dz++ {
					for dx := -1; dx <= 1; dx++ {
						ny, nz, nx := cy+dy, cz+dz, cx+dx
						if ny >= 0 && ny < g.WY && nz >= 0 && nz < g.WZ && nx >= 0 && nx < g.WX {
							g.World[ny][nz][nx] = BlockAir
						}
					}
				}
			}
		}
	}
}

func (g *Game) GetBlock(x, y, z int) uint8 {
	if x < 0 || x >= g.WX || y < 0 || y >= g.WY || z < 0 || z >= g.WZ {
		return BlockAir
	}
	return g.World[y][z][x]
}

func (g *Game) SetBlock(x, y, z int, b uint8) {
	if x < 0 || x >= g.WX || y < 0 || y >= g.WY || z < 0 || z >= g.WZ {
		return
	}
	g.World[y][z][x] = b
}

func (g *Game) MovePlayer(dx, dy, dz float64) {
	g.PlayerX += dx
	g.PlayerY += dy
	g.PlayerZ += dz

	// Collision detection
	if g.Collides(int(g.PlayerX), int(g.PlayerY), int(g.PlayerZ)) {
		g.PlayerX -= dx
		g.PlayerY -= dy
		g.PlayerZ -= dz
	}
}

func (g *Game) Jump() {
	if g.OnGround || g.Flying {
		g.PlayerVY = 0.4
		g.OnGround = false
	}
}

func (g *Game) CycleHotbar() {
	g.HotbarSel = (g.HotbarSel + 1) % 9
}

func (g *Game) SelectHotbar(slot int) {
	if slot >= 0 && slot < 9 {
		g.HotbarSel = slot
	}
}

func (g *Game) PlaceBlock() {
	px, py, pz := int(g.PlayerX), int(g.PlayerY+0.5), int(g.PlayerZ)
	fx, fy, fz := px, py, pz+1

	if fx >= 0 && fx < g.WX && fy >= 0 && fy < g.WY && fz >= 0 && fz < g.WZ {
		if g.World[fy][fz][fx] == BlockAir {
			g.World[fy][fz][fx] = g.Hotbar[g.HotbarSel]
			if !g.Creative {
				g.Inventory[g.Hotbar[g.HotbarSel]]--
				if g.Inventory[g.Hotbar[g.HotbarSel]] <= 0 {
					delete(g.Inventory, g.Hotbar[g.HotbarSel])
				}
			}
		}
	}
}

func (g *Game) BreakBlock() {
	px, py, pz := int(g.PlayerX), int(g.PlayerY+0.5), int(g.PlayerZ)
	fx, fy, fz := px, py, pz+1

	if fx >= 0 && fx < g.WX && fy >= 0 && fy < g.WY && fz >= 0 && fz < g.WZ {
		b := g.World[fy][fz][fx]
		if b != BlockAir && b != BlockBedrock {
			g.World[fy][fz][fx] = BlockAir
			if !g.Creative {
				g.Inventory[b]++
			}
		}
	}
}

func (g *Game) ToggleCreative() {
	g.Creative = !g.Creative
}

func (g *Game) PrintDebug() {
	fmt.Printf("\n=== DEBUG ===\n")
	fmt.Printf("Pos: %.2f, %.2f, %.2f\n", g.PlayerX, g.PlayerY, g.PlayerZ)
	fmt.Printf("OnGround: %v, Flying: %v, Creative: %v\n", g.OnGround, g.Flying, g.Creative)
	fmt.Printf("HotbarSel: %d, Block: %s\n", g.HotbarSel, BlockNames[g.Hotbar[g.HotbarSel]])
	fmt.Printf("Frame: %d, DayTime: %.0f\n", g.FrameCount, g.DayTime)
	fmt.Printf("World: %dx%dx%d\n", g.WX, g.WY, g.WZ)
	fmt.Printf("==============\n")
}

func (g *Game) Collides(x, y, z int) bool {
	for dy := 0; dy < 2; dy++ {
		for dz := -1; dz <= 1; dz++ {
			for dx := -1; dx <= 1; dx++ {
				bx, by, bz := x+dx, y+dy, z+dz
				if g.GetBlock(bx, by, bz) != BlockAir {
					return true
				}
			}
		}
	}
	return false
}

// Ray march to find targeted block
func (g *Game) Raycast() (int, int, int, int, int, int, bool) {
	px, py, pz := int(g.PlayerX), int(g.PlayerY+0.5), int(g.PlayerZ)
	for d := 1; d <= 8; d++ {
		fx, fy, fz := px, py, pz+d
		if fx >= 0 && fx < g.WX && fy >= 0 && fy < g.WY && fz >= 0 && fz < g.WZ {
			b := g.World[fy][fz][fx]
			if b != BlockAir {
				return px, py, pz + d - 1, fx, fy, fz, true
			}
		}
	}
	return 0, 0, 0, 0, 0, 0, false
}

func (g *Game) Render() {
	fmt.Print("\033[H") // move cursor home

	// Update physics
	if !g.Flying {
		g.PlayerVY -= 0.02 // gravity
		if g.PlayerVY < -0.5 {
			g.PlayerVY = -0.5
		}
	}
	g.PlayerX += g.PlayerVX
	g.PlayerY += g.PlayerVY
	g.PlayerZ += g.PlayerVZ

	// Ground check
	if g.PlayerY <= 0 {
		g.PlayerY = 0
		g.PlayerVY = 0
		g.OnGround = true
	} else if g.GetBlock(int(g.PlayerX), int(g.PlayerY-1), int(g.PlayerZ)) != BlockAir {
		g.PlayerY = float64(int(g.PlayerY-1) + 1)
		g.PlayerVY = 0
		g.OnGround = true
	} else {
		g.OnGround = false
	}

	if g.Flying {
		g.PlayerVY = 0
		g.OnGround = true
	}

	// Camera
	camX := int(g.PlayerX)
	camY := int(g.PlayerY + 0.5)
	camZ := int(g.PlayerZ)

	// Draw frame
	var sb strings.Builder

	// Title bar
	sb.WriteString("\033[36m=== Minecraft Go ===\033[0m  ")
	dayNight := "Day"
	if int(g.DayTime)%24000 > 12000 {
		dayNight = "Night"
	}
	sb.WriteString(fmt.Sprintf("Seed:%d [%s] ", g.Seed, dayNight))
	if g.Creative {
		sb.WriteString("\033[33m[Creative]\033[0m ")
	}
	if g.Flying {
		sb.WriteString("\033[33m[Flying]\033[0m ")
	}
	sb.WriteString(fmt.Sprintf("Pos: %.0f,%.0f,%.0f", g.PlayerX, g.PlayerY, g.PlayerZ))
	sb.WriteString("\n")

	// Day/Night sky color
	skyColor := "\033[34;44m" // blue sky
	if int(g.DayTime)%24000 > 12000 {
		skyColor = "\033[30;40m" // dark sky
	}

	// Render 3D view (simplified first-person cross-section)
	for row := g.Height; row >= 0; row-- {
		relY := row - g.Height/2
		for col := 0; col < g.Width; col++ {
			relX := col - g.Width/2

			// Project ray (simplified: just map screen coords to world)
			worldX := camX + relX/2
			worldZ := camZ + relY/2
			worldY := camY + relY/4

			if worldX >= 0 && worldX < g.WX && worldY >= 0 && worldY < g.WY && worldZ >= 0 && worldZ < g.WZ {
				b := g.World[worldY][worldZ][worldX]
				if b == BlockAir {
					// Draw sky / distance fog
					if worldY > 20 {
						sb.WriteString(skyColor + "  \033[0m")
					} else {
						// Underground / void
						sb.WriteString("\033[30;40m  \033[0m")
					}
				} else {
					color := BlockColors[b]
					ch := BlockChars[b]
					sb.WriteString(color + ch + ch + "\033[0m")
				}
			} else {
				sb.WriteString("\033[30;40m  \033[0m")
			}
		}
		sb.WriteString("\n")
	}

	// Hotbar
	sb.WriteString("\n\033[33mHotbar:\033[0m ")
	for i := 0; i < 9; i++ {
		sel := " "
		if i == g.HotbarSel {
			sel = ">"
		}
		color := BlockColors[g.Hotbar[i]]
		count := ""
		if g.Inventory[g.Hotbar[i]] > 0 {
			count = fmt.Sprintf(":%d", g.Inventory[g.Hotbar[i]])
		}
		sb.WriteString(fmt.Sprintf("%s%s%s%s\033[0m ",
			sel, color, BlockNames[g.Hotbar[i]][:3], count))
	}

	sb.WriteString("\n\n\033[32mWASD=move Space=jump F=place G=break 1-9=slot E=cycle C=creative T=fly Q=quit\033[0m")

	// Print crosshair and directions
	sb.WriteString("\n\033[36mControls: wasd=move SPACE=jump F=place G=break 1-9=sel E=cycle C=creative T=fly Q=quit\033[0m")

	fmt.Print(sb.String())

	g.DayTime += 0.5
	g.FrameCount++
}

func (g *Game) ShowHelp() {
	fmt.Print("\033[H")
	help := `\033[36m=== Minecraft Go - Help ===\033[0m
\033[33mMovement:\033[0m
  W/A/S/D  - Move forward/left/backward/right
  SPACE    - Jump
  T        - Toggle flying
\033[33mBuilding:\033[0m
  F        - Place block in front
  G        - Break block in front
  1-9      - Select hotbar slot
  E        - Cycle hotbar
\033[33mGame:\033[0m
  C        - Toggle creative mode (unlimited blocks)
  Q/ESC    - Quit
\033[33mCommands:\033[0m
  seed     - Show world seed
  pos      - Show player position
  help     - Show this help
\033[33mTerrain:\033[0m
  Generated using seed-based noise with grass, dirt, stone,
  trees, caves, and varied height. Explore the world!
`
	fmt.Println(help)
	fmt.Println("\n\033[33mPress any key to continue...\033[0m")
	buf := make([]byte, 1)
	os.Stdin.Read(buf)
}

package main

import (
	"fmt"
	"os"
	"os/exec"
	"strconv"
	"strings"
)

// RawTerminalRestorer restores terminal on close
type RawTerminalRestorer struct{}

func (r *RawTerminalRestorer) Close() error {
	// Restore terminal echo
	exec.Command("stty", "echo").Run()
	return nil
}

func enableRawTerminal() (*RawTerminalRestorer, error) {
	// Try to set raw mode with stty
	cmd := exec.Command("stty", "-F", "/dev/tty", "-echo", "-icanon", "-isig", "-ixon")
	err := cmd.Run()
	if err != nil {
		// stty might not accept -F on some systems; try another approach
		cmd2 := exec.Command("stty", "-echo", "-icanon", "-isig")
		err2 := cmd2.Run()
		if err2 != nil {
			return nil, fmt.Errorf("cannot set raw terminal: %v, %v", err, err2)
		}
	}
	return &RawTerminalRestorer{}, nil
}

func getTerminalSize() (width, height int, err error) {
	cmd := exec.Command("stty", "size")
	cmd.Stdin = os.Stdin
	out, err := cmd.Output()
	if err != nil {
		return 80, 30, nil
	}
	parts := strings.Split(strings.TrimSpace(string(out)), " ")
	if len(parts) == 2 {
		h, _ := strconv.Atoi(parts[0])
		w, _ := strconv.Atoi(parts[1])
		if w > 0 && h > 0 {
			return w, h, nil
		}
	}
	return 80, 30, nil
}
